/// </summary>
public sealed class ScheduleRegistryRegisterTests
{
    private static readonly DateTimeOffset Now =
        new(2026, 6, 13, 12, 0, 0, TimeSpan.Zero);

    /// <summary>
    /// Verifies registering a new job adds it to the registry and persists it.
    /// </summary>
